insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('93a92741-afb8-5790-a53d-f067988ffaeb', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 67 year old man presents to the Emergency Department with pain in his left groin. He suddenly collapsed and cannot move or lift his leg. He takes alendronate. What is the SINGLE most likely diagnosis?', 'Alendronate tells you he has osteoporosis. Groin pain and inability to lift the leg (straight leg raise) after a low-energy fall in an older person is a fractured neck of femur until proven otherwise, typically with a shortened, externally rotated leg. Posterior hip dislocation needs high-energy trauma (such as dashboard injury) and gives a shortened, internally rotated, adducted leg. Long-term bisphosphonates also predispose to atypical subtrochanteric/femoral shaft fractures, often preceded by thigh pain, but groin pain points to the neck of femur. Get AP pelvis and lateral hip X-rays.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
