insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('be02747e-1c6f-56de-a0e4-cd113ca4b6fc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'An older woman develops sudden pain in the upper part of her arm after carrying heavy loads. There is a bulge in the lower arm when she flexes her elbow. What is the SINGLE most likely diagnosis?', 'Sudden pain in the upper arm (sometimes with a ''pop'') during heavy lifting in an older person suggests rupture of the long head of biceps tendon. It produces a ''Popeye'' bulge of the retracted muscle belly. It usually causes little functional loss (the short head and brachialis remain) and is managed conservatively in older patients. Supraspinatus tears cause pain and weakness on abduction rather than an upper-arm bulge. Note: the original question gave no examination finding; the ''Popeye'' sign has been added to make the stem discriminating.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
