insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6486e664-9643-57e6-997f-eeeca23ba92a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000004', 'sba', 'A 17 year old man has a history of easy bruising. On examination he is obese with purple abdominal striae. His serum potassium is 2.3 mmol/L. What is the SINGLE most likely diagnosis?', 'Easy bruising (thin skin), central obesity and striae point to Cushing''s syndrome. Hypokalaemia is more marked with ectopic ACTH or high cortisol levels, because cortisol saturates 11-beta-HSD2 and acts on mineralocorticoid receptors. Conn''s syndrome gives hypertension and hypokalaemia but not obesity or bruising. Addison''s causes hyperkalaemia. Screen with an overnight dexamethasone suppression test or 24-hour urinary free cortisol.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
