  ('647e942b-23b1-5a87-8e93-7e106008a388', '6486e664-9643-57e6-997f-eeeca23ba92a', 'B', 'Addison''s disease', false, 1),
  ('6e810e3f-9824-584b-8e0c-3a8edc441901', '6486e664-9643-57e6-997f-eeeca23ba92a', 'C', 'Cushing''s syndrome', true, 2),
