  ('426617b7-1db2-5f50-b35b-ca43d8dcdaa6', '4513da24-9839-5477-82ce-101e1f3eaa4a', 'A', 'Fat embolism', false, 0),
  ('bd1ec12a-7812-518a-a54c-bd4b4b8e69c1', '4513da24-9839-5477-82ce-101e1f3eaa4a', 'B', 'Severe bleeding (hypovolaemia)', true, 1),
  ('470f3762-01cf-5700-9d7c-262db4c3c7b1', '4513da24-9839-5477-82ce-101e1f3eaa4a', 'C', 'Reaction to anaesthesia', false, 2),
  ('2c675534-a777-56dc-b4be-9edfc95e6b4f', '4513da24-9839-5477-82ce-101e1f3eaa4a', 'D', 'Pulmonary embolism', false, 3),
  ('a1a8baed-bf8e-5b02-a492-608546426767', '4513da24-9839-5477-82ce-101e1f3eaa4a', 'E', 'Cardiac tamponade', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5e5f3e66-0313-5da1-b2b0-e73b9effb3e1', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A 26 year old man has hereditary haemorrhagic telangiectasia and is planning to start a family. What is the mode of inheritance?', 'Hereditary haemorrhagic telangiectasia (Osler-Weber-Rendu) is autosomal dominant (ENG, ACVRL1 and SMAD4 mutations), so each child has a 50% chance of inheriting it. Penetrance is age-dependent but almost complete by adulthood. It causes epistaxis, mucocutaneous telangiectasia and arteriovenous malformations in the lung, liver and brain, so screening for pulmonary AVMs is recommended, especially before pregnancy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
