  ('dd2131c0-67b8-55ed-8ec7-df692b962e1e', '5e5f3e66-0313-5da1-b2b0-e73b9effb3e1', 'A', 'Autosomal dominant with incomplete penetrance', false, 0),
  ('0b6dc750-7333-54bb-bb35-087e33ea323c', '5e5f3e66-0313-5da1-b2b0-e73b9effb3e1', 'B', 'Autosomal recessive with incomplete penetrance', false, 1),
  ('72aeb2fa-37fb-5376-a0cd-94423741e4dd', '5e5f3e66-0313-5da1-b2b0-e73b9effb3e1', 'C', 'Autosomal dominant', true, 2),
