  ('99912791-02db-5a86-bd46-80aa61ed0cb6', '77eb2f34-a9e2-5a6b-b83a-580d471724f0', 'B', 'Rifampicin', false, 1),
  ('d9f27afc-7dde-57ec-afa5-dbb9752bda0c', '77eb2f34-a9e2-5a6b-b83a-580d471724f0', 'C', 'Gentamicin', false, 2),
  ('1dcbf5b7-dbfa-50ed-8054-c00a380a4dc0', '77eb2f34-a9e2-5a6b-b83a-580d471724f0', 'D', 'Flucloxacillin', true, 3),
