  ('f27d6761-eff6-58fa-ad77-b7360d38abf7', 'e9c2019a-422e-597c-8a5f-fefea0e2a04b', 'A', 'Colorectal carcinoma', false, 0),
  ('aa8697d2-25ad-5b95-98ee-41fa96408f79', 'e9c2019a-422e-597c-8a5f-fefea0e2a04b', 'B', 'Adhesions', true, 1),
  ('91d695a9-3685-514d-9a72-c989afedc0f4', 'e9c2019a-422e-597c-8a5f-fefea0e2a04b', 'C', 'Crohn''s stricture', false, 2),
  ('9ee25c98-9286-5d3c-b94f-84b6f68856dd', 'e9c2019a-422e-597c-8a5f-fefea0e2a04b', 'D', 'Obstructed femoral hernia', false, 3),
