  ('63f8c072-0ca6-5171-968c-03849dbac2fb', '45260dca-11cb-5b24-a69c-32451177734f', 'A', 'Anterior shoulder dislocation', false, 0),
  ('b89feb5c-3755-5cd0-aee3-708b2a5fd731', '45260dca-11cb-5b24-a69c-32451177734f', 'B', 'Patellar tendon rupture', false, 1),
  ('2630a220-4b01-53d7-8c5d-3823d400df2e', '45260dca-11cb-5b24-a69c-32451177734f', 'C', 'Thoracolumbar spine fracture', true, 2),
  ('96941de7-b087-564c-90d5-51dac8fdaf9c', '45260dca-11cb-5b24-a69c-32451177734f', 'D', 'Fracture of the fibular neck', false, 3),
  ('06024e0f-8315-57d4-bfc0-2ff2ed7575e8', '45260dca-11cb-5b24-a69c-32451177734f', 'E', 'Scaphoid fracture', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000011', 'sba', 'A 61 year old man who drinks heavily and has type 2 diabetes cannot fully straighten his right ring and little fingers. The palm is not painful. His hand is shown in the image. Which structure is primarily affected?', 'The image shows Dupuytren''s contracture: palpable cords and nodules in the palm with fixed flexion of the ring and little fingers. It is a fibroproliferative disease of the palmar aponeurosis (fascia), linked to alcohol, diabetes, smoking, family history (autosomal dominant), epilepsy medication and manual work. Treatment (needle fasciotomy, collagenase or fasciectomy) is considered when the hand cannot be laid flat on a table (positive Hueston tabletop test) or the MCP contracture is about 30 degrees or more.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dupuytren''s2010.JPG')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6584ac9f-334b-5fb3-9ec7-04a555719d88', 'dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'A', 'Proximal interphalangeal joint capsule only', false, 0),
  ('ba52a048-8a81-59a4-8c35-befa0f6ec97b', 'dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'B', 'Flexor digitorum profundus tendon', false, 1),
  ('ac1f35a9-63ff-599d-bf89-7fc71b80d1fe', 'dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'C', 'Ulnar nerve', false, 2),
  ('ddd8ce35-aae7-53a2-9704-33cab8306735', 'dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'D', 'Palmar aponeurosis (palmar fascia)', true, 3),
  ('668b239e-4071-5c17-a2e5-e41eb946261e', 'dd9d623e-c72b-55d7-8c90-8b9c7c816e63', 'E', 'Flexor tendon sheath (trigger finger)', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000019', 'sba', 'A 64 year old man has had recurrent attacks of painful, swollen joints for 10 years. He has hypertension and takes bendroflumethiazide. His hand is shown in the image; chalky white material is discharging from the swellings. He is between attacks. What is the SINGLE most appropriate long-term management?', 'The image shows chronic tophaceous gout, with urate tophi discharging chalky material. Tophi are a firm indication for urate-lowering therapy. NICE (2022) and BSR recommend a treat-to-target approach: allopurinol (or febuxostat) titrated to keep serum urate below 360 µmol/L, or below 300 µmol/L if tophi or frequent attacks. Give colchicine or an NSAID as prophylaxis when starting. Consider switching the thiazide (for example to losartan, which has a mild uricosuric effect).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Tophigout.JPG')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('1b83c380-8699-59f1-a0a3-9a4314123908', 'd0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'A', 'Methotrexate', false, 0),
  ('3403f744-2011-5407-972e-0033b258176d', 'd0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'B', 'Long-term oral prednisolone', false, 1),
  ('7dc16095-fd16-5ce7-8114-6ad78da13f29', 'd0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'C', 'Oral colchicine during attacks only', false, 2),
  ('23f43842-6821-5aa1-97ef-a8df0dfc6fda', 'd0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'D', 'Intra-articular steroid injections into each swelling', false, 3),
  ('f1c2b846-bce3-5252-a8cb-2907286ae1b7', 'd0e1ce9e-edab-5b3b-972b-4bcbb452285e', 'E', 'Allopurinol titrated to a serum urate below 300 µmol/L', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 72 year old retired farmer has a slowly enlarging, painless lesion on the tip of his nose that has been present for 18 months. His lesion is shown in the image. It is pearly with visible telangiectasia. What is the SINGLE most likely diagnosis?', 'The image shows a pearly, waxy, red nodule with telangiectasia on sun-exposed skin of an older man: a nodular basal cell carcinoma. BCCs grow slowly and invade locally but almost never metastasise, so most need a routine (not two-week-wait) referral. Lesions in high-risk sites such as the nose and around the eyes are referred to specialists, and Mohs surgery may be used. A keratoacanthoma grows rapidly over weeks with a central keratin plug.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/BCC_Nodular_type.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('718a379c-9aab-5e4f-a37c-e2ea061217b4', 'cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'A', 'Keratoacanthoma', false, 0),
  ('9ae850b2-a17c-5078-8aa1-b45b6a21ab9c', 'cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'B', 'Squamous cell carcinoma', false, 1),
  ('2c7e46b1-4483-5bd7-a1ad-67b6f8e586e9', 'cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'C', 'Nodular basal cell carcinoma', true, 2),
  ('0b291fb8-f3ab-5dc1-b37b-efa8f2b46a9d', 'cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'D', 'Sebaceous hyperplasia', false, 3),
  ('61968e5b-0d31-5b38-93f6-1a7a74ed33c3', 'cd101a70-6ee3-5d14-ac28-337d66ccdd64', 'E', 'Seborrhoeic keratosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('51339372-aec1-5b48-9066-907a31679f17', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 77 year old woman has a slowly enlarging, flat pigmented lesion on her cheek. It is irregular in outline and contains several shades of brown and black. Her lesion is shown in the image. What is the SINGLE most appropriate management?', 'The lesion has features of melanoma (asymmetry, irregular border, colour variation and change): on sun-damaged facial skin in an older person this is typically lentigo maligna melanoma or superficial spreading melanoma. NICE uses the weighted 7-point checklist (major: change in size, shape or colour; minor: diameter 7 mm or more, inflammation, oozing, change in sensation). A score of 3 or more, or strong clinical suspicion, needs a two-week-wait referral. Destroying the lesion (cryotherapy) or discarding tissue would prevent histological staging.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Melanoma5.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('4a74c94c-3170-5702-b505-44ccd966b6a2', '51339372-aec1-5b48-9066-907a31679f17', 'A', 'Suspected cancer pathway (two-week wait) referral to dermatology', true, 0),
  ('303df931-e752-5bbb-a22c-6f87d0e91224', '51339372-aec1-5b48-9066-907a31679f17', 'B', 'Reassure and review in 6 months', false, 1),
  ('83848fa8-be5c-56e5-9809-0895755135ef', '51339372-aec1-5b48-9066-907a31679f17', 'C', 'Cryotherapy in primary care', false, 2),
  ('5b73403e-a877-5ab7-a64c-eee2db552615', '51339372-aec1-5b48-9066-907a31679f17', 'D', 'Shave excision in primary care and discard the specimen', false, 3),
  ('c2e0c29f-5a34-51a2-9da2-321ace1b94cf', '51339372-aec1-5b48-9066-907a31679f17', 'E', 'Topical 5-fluorouracil', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 6 year old boy has had crusted lesions around his nose for 4 days. He is otherwise well and has no fever. The rash is shown in the image; it is localised, with golden-yellow crusts and no blisters. What is the SINGLE most appropriate first-line treatment?', 'The image shows non-bullous impetigo (honey-coloured crusts around the nose), usually caused by Staphylococcus aureus. NICE (NG153) recommends hydrogen peroxide 1% cream for 5 days for localised non-bullous impetigo in people who are not systemically unwell. Topical fusidic acid is used if hydrogen peroxide is unsuitable. Oral flucloxacillin is for widespread disease, bullous impetigo or systemic illness. Keep the child off school until the lesions have crusted and healed, or for 48 hours after starting antibiotics.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Impetigo_Nase.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('81a9cd9c-dd2b-56cd-ad2d-9bdecfd12456', 'f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'A', 'Hydrogen peroxide 1% cream', true, 0),
  ('61a42af2-c818-56eb-a6a2-b3cf57c8bc4f', 'f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'B', 'Topical hydrocortisone 1% cream', false, 1),
  ('8ccdc955-df6e-5208-9137-b400e465f442', 'f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'C', 'Topical clotrimazole', false, 2),
  ('9091456d-a433-5864-9bb0-354093dadb59', 'f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'D', 'Oral flucloxacillin for 7 days', false, 3),
  ('378186fd-dc14-597d-bfdd-a8f75420ca7e', 'f3ba3698-6868-50dd-9447-99a1ab8dae7f', 'E', 'Oral aciclovir', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 45 year old man has had itchy, well-defined, salmon-pink plaques with silvery scale on his elbows and knees for 6 months. The rash on his elbow is shown in the image. What is the SINGLE most appropriate first-line treatment for these trunk and limb plaques?', 'The image shows chronic plaque psoriasis on an extensor surface. NICE recommends a potent corticosteroid once daily plus a vitamin D analogue (such as calcipotriol) once daily, applied separately (one in the morning, one in the evening), for up to 4 weeks for trunk and limb psoriasis. Systemic steroids are avoided because they can cause rebound or pustular flares. Phototherapy and systemic agents (such as methotrexate) are second- and third-line treatments. Screen for psoriatic arthritis (PEST questionnaire).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Psoriasis_in_elbow.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d2f232de-184a-5bf2-a31a-2f5d97ffc6ec', '8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'A', 'Oral methotrexate', false, 0),
  ('1299a171-94f3-5c81-8b82-aba4c4234ddc', '8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'B', 'Narrowband UVB phototherapy as first-line', false, 1),
  ('df1c7e87-c605-5636-86a8-7e81fe4e7f85', '8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'C', 'Oral prednisolone', false, 2),
  ('c5989307-e9cd-55d2-85fa-b5f7bbe921c6', '8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'D', 'A potent topical corticosteroid once daily plus a topical vitamin D analogue once daily (at different times)', true, 3),
  ('c6ad5f1b-2916-5c5a-8d09-8b0c0a234b61', '8f97bf42-0037-5e4e-8f76-28f081d9d4dd', 'E', 'Topical clotrimazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f56ed65b-9eef-54a6-9160-fe7357925879', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000012', 'sba', 'A 31 year old woman has had extremely itchy hands for 3 weeks, worse at night. Her partner is also itchy. Her hand is shown in the image, with papules and burrows in the finger web spaces. What is the SINGLE most appropriate management?', 'The image shows scabies (Sarcoptes scabiei), with itchy papules and burrows in the finger webs and wrists, and itching that is worse at night and shared by contacts. Permethrin 5% is applied to the whole body from the neck down (including the scalp and face in young children and older people), left on for 8-12 hours, then repeated after 7 days. All household and sexual contacts must be treated at the same time, even without symptoms. Wash bedding and clothing at 50°C or above. Itching can last up to 4-6 weeks after successful treatment.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/ScabiesD06.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('714c3dc4-dac6-5b17-a065-07119beae1bb', 'f56ed65b-9eef-54a6-9160-fe7357925879', 'A', 'Permethrin 5% cream for her and all close contacts at the same time, repeated after 7 days', true, 0),
  ('3a50c4ec-b236-5f2a-a711-f7d0a6a3f7ee', 'f56ed65b-9eef-54a6-9160-fe7357925879', 'B', 'Oral flucloxacillin', false, 1),
  ('c98b9811-744a-53e4-99bf-8b3a42bff662', 'f56ed65b-9eef-54a6-9160-fe7357925879', 'C', 'Potent topical steroid to the hands only', false, 2),
  ('54724db1-7970-51ce-804b-a253ffa5a06a', 'f56ed65b-9eef-54a6-9160-fe7357925879', 'D', 'Oral antihistamine only', false, 3),
  ('e7d3d759-9a41-56f5-b87e-38eed111cc1e', 'f56ed65b-9eef-54a6-9160-fe7357925879', 'E', 'Treat her alone with a single application of permethrin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 38 year old man went hiking in the New Forest 10 days ago. He has an expanding, painless red rash on his thigh. It is about 8 cm across and is shown in the image. He is otherwise well. What is the SINGLE most appropriate management?', 'The image shows erythema migrans, which is diagnostic of Lyme disease (Borrelia burgdorferi, transmitted by Ixodes ticks). NICE recommends treating on clinical diagnosis without testing, because serology is often negative early on. The treatment is oral doxycycline 100 mg twice daily (or 200 mg once daily) for 21 days. Amoxicillin is an alternative in pregnancy and for children under 9.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Erythema_migrans_-_erythematous_rash_in_Lyme_disease_-_PHIL_9875.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('84fe8b35-c8ea-57b5-b303-4f06ffc3c426', '862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'A', 'Oral flucloxacillin for 7 days', false, 0),
  ('853bad5a-603a-5a1f-a104-3eb3bb5048e4', '862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'B', 'Oral doxycycline for 21 days without waiting for serology', true, 1),
  ('f6b30c77-7ec3-587f-91a0-b13061c05289', '862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'C', 'Lyme serology, and treat only if positive', false, 2),
  ('682034df-93b7-521e-a0bf-0f20160b2481', '862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'D', 'Reassure; it will fade without treatment', false, 3),
  ('4b9be832-9b2b-542e-83a2-28ee6acc40bd', '862d2f65-4b4a-5383-8e05-015f4d3bc25b', 'E', 'Topical clotrimazole', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0823c8e1-afd9-5774-b36a-55ec86d6984f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000010', 'sba', 'A 66 year old woman had burning pain on the left side of her chest for 3 days. A painful blistering rash then appeared yesterday; it is shown in the image and does not cross the midline. She is otherwise well. What is the SINGLE most appropriate management?', 'The image shows herpes zoster (shingles), a unilateral painful vesicular rash in a dermatomal distribution caused by reactivation of varicella-zoster virus. NICE CKS advises an oral antiviral within 72 hours of rash onset for people aged 50 or over (to reduce the risk of postherpetic neuralgia), as well as for those who are immunosuppressed, have severe pain or rash, or have non-truncal involvement. Shingles affecting the ophthalmic division (Hutchinson''s sign) needs same-day ophthalmology review.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Shingles_on_the_chest.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6e71408b-5b05-5b7f-ace6-bfe8de33a715', '0823c8e1-afd9-5774-b36a-55ec86d6984f', 'A', 'Topical hydrocortisone', false, 0),
  ('d4d31212-de3e-5ebc-9b9d-76564d8d83f2', '0823c8e1-afd9-5774-b36a-55ec86d6984f', 'B', 'Oral flucloxacillin', false, 1),
  ('588d27eb-c1e8-54df-aa06-42daf8423470', '0823c8e1-afd9-5774-b36a-55ec86d6984f', 'C', 'Oral prednisolone alone', false, 2),
  ('9c5b7010-38ee-5349-a608-4178d0b88fb7', '0823c8e1-afd9-5774-b36a-55ec86d6984f', 'D', 'Reassurance only, as antivirals are not indicated over 50', false, 3),
  ('f9e5c3ba-9fa3-5213-aa37-fc6a91daa521', '0823c8e1-afd9-5774-b36a-55ec86d6984f', 'E', 'Oral aciclovir (or valaciclovir) for 7 days, with analgesia', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dc45dff2-b53b-5914-901b-e94b31233497', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 16 month old boy had a mild cold last week. He now has bright red cheeks, shown in the image, and a lacy rash on his arms. He is well and playing normally. What is the SINGLE most likely causative organism?', 'The image shows the "slapped cheek" appearance of erythema infectiosum (fifth disease), caused by parvovirus B19, often followed by a lacy reticular rash on the limbs. The child is no longer infectious once the rash appears, so school exclusion is not needed. Parvovirus can cause aplastic crisis in people with haemolytic anaemias (such as sickle cell disease), and in pregnancy can cause fetal anaemia and hydrops, so pregnant contacts should be tested.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Fifth_disease_cropped.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('68cb8c30-a624-5b00-a239-d9df812ab44c', 'dc45dff2-b53b-5914-901b-e94b31233497', 'A', 'Human herpesvirus 6', false, 0),
  ('c912b3da-d6dc-52ef-95df-43f55ce50e35', 'dc45dff2-b53b-5914-901b-e94b31233497', 'B', 'Measles virus', false, 1),
  ('736c4cae-6763-5d53-b5d6-f6ebc02bce7a', 'dc45dff2-b53b-5914-901b-e94b31233497', 'C', 'Group A Streptococcus', false, 2),
  ('b0c0bf9c-458c-5cf4-aefc-9eddfdc876fe', 'dc45dff2-b53b-5914-901b-e94b31233497', 'D', 'Parvovirus B19', true, 3),
  ('d195d0e0-db1c-5734-a7ff-56e2f5b6ddef', 'dc45dff2-b53b-5914-901b-e94b31233497', 'E', 'Rubella virus', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000009', 'sba', 'A 5 year old girl has had several small, painless, pearly papules on her trunk for 2 months. Each has a central dimple; they are shown in the image. She has mild eczema and is otherwise well. Her mother wants them removed before starting school. What is the SINGLE most appropriate advice?', 'The image shows molluscum contagiosum (a poxvirus): firm, pearly, umbilicated papules. NICE CKS advises reassurance, as lesions usually resolve within 18 months (sometimes longer), and treatment is not routinely recommended. There is no need for school or swimming exclusion. Advise not sharing towels and not scratching. If there is eczema around the lesions, it can be treated with emollients and a mild steroid. Refer if the lesions are on the eyelid with red eye, the person is immunocompromised, or there are extensive lesions in an adult (consider HIV).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Molluscaklein.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d3e41c09-977d-5eca-b3cc-d270097c758a', '655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'A', 'Cryotherapy to all lesions', false, 0),
  ('c44e0480-0db9-5397-ba46-c010c502b2d0', '655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'B', 'Topical potent corticosteroid', false, 1),
  ('cc2cfb56-9112-599b-b091-b23ce12427ca', '655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'C', 'Oral aciclovir', false, 2),
  ('0006a15e-1af1-54bb-9ee0-efd4217dd055', '655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'D', 'Keep her off school until the lesions clear', false, 3),
  ('2e21772d-f39e-5366-bcc2-f8c86ab42a8f', '655f3b1d-6d0d-5b3a-9361-5205e434bed0', 'E', 'Reassure that they are self-limiting (usually within 18 months) and no school exclusion is needed', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dd105eb0-b194-596a-ba2a-c870230cbf64', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 27 year old woman with a BMI of 38 has had daily headaches for 2 months. They are worse on lying down, and she has transient visual obscurations. Neurological examination is otherwise normal and MRI/MR venography of the brain is normal. Fundoscopy of both eyes looks like the image shown. What is the SINGLE most likely diagnosis?', 'The image shows papilloedema (swollen optic disc with blurred margins and obscured vessels). In a young obese woman with headaches, visual obscurations and normal imaging, the likely diagnosis is idiopathic intracranial hypertension. A lumbar puncture shows a raised opening pressure (over 25 cmH2O) with normal CSF. Management is weight loss and acetazolamide; urgent surgery (shunt or optic nerve sheath fenestration) is used if vision is threatened. Check for drug causes such as tetracyclines and retinoids.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Papilledema.jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('5c9cf037-cd97-50f2-99a5-eff01ca5de15', 'dd105eb0-b194-596a-ba2a-c870230cbf64', 'A', 'Migraine with aura', false, 0),
  ('0600ece1-becf-5afa-8805-36149fd42806', 'dd105eb0-b194-596a-ba2a-c870230cbf64', 'B', 'Optic neuritis', false, 1),
  ('466f054c-e256-5ac0-81d2-a0e3cc198efb', 'dd105eb0-b194-596a-ba2a-c870230cbf64', 'C', 'Idiopathic intracranial hypertension', true, 2),
  ('785cbcc2-6bc6-5dee-8ffa-5780ed9937ae', 'dd105eb0-b194-596a-ba2a-c870230cbf64', 'D', 'Medication-overuse headache', false, 3),
  ('48af6047-ad6d-5db5-b6b6-85a58f9162cf', 'dd105eb0-b194-596a-ba2a-c870230cbf64', 'E', 'Central retinal vein occlusion', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000015', 'sba', 'A 74 year old man with atrial fibrillation who is not anticoagulated had sudden, painless, complete loss of vision in his left eye 2 hours ago. He has a left relative afferent pupillary defect. His left fundus is shown in the image. What is the SINGLE most likely diagnosis?', 'The image shows a pale, oedematous retina with a cherry-red spot at the macula (the fovea keeps its choroidal blood supply): central retinal artery occlusion. Causes include emboli (carotid disease, AF) and giant cell arteritis, so check ESR/CRP in older patients. Refer as an emergency (it is treated as a stroke equivalent, with stroke workup). Central retinal vein occlusion gives a "stormy sunset" fundus with widespread haemorrhages.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2', 'image_url', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cherry_red_spot_in_patient_with_central_retinal_artery_occlusion_(CRAO).jpg')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('cb71ee19-b55d-52a5-870c-f3157563449b', 'e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'A', 'Retinal detachment', false, 0),
  ('f9c29407-08e2-5412-8f4c-333796fdac9d', 'e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'B', 'Central retinal vein occlusion', false, 1),
  ('a81878b6-6d6a-5cbb-9601-27eb3a6a996d', 'e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'C', 'Central retinal artery occlusion', true, 2),
  ('f5ee5e8e-b0f2-57c0-bdee-612c1ca4b00c', 'e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'D', 'Acute angle-closure glaucoma', false, 3),
  ('0e073833-f087-5797-9c09-b9ca11ee040e', 'e0d55ec3-6d8c-556e-8885-0eb8c7abfabc', 'E', 'Vitreous haemorrhage', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bab63b51-b37d-51b4-89f3-e656110fce7e', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 45 year old woman has a thyroidectomy. The next day she has a weak voice and cannot reach high-pitched notes when singing. Her vocal cords move normally on laryngoscopy. Which nerve has MOST likely been injured?', 'The external laryngeal nerve runs with the superior thyroid artery and supplies cricothyroid, which tenses the vocal cords. Injury causes a weak, easily fatigued voice and loss of high pitch, with normal-looking cord movement. Recurrent laryngeal nerve injury causes hoarseness from a paralysed cord. The internal laryngeal nerve carries sensation above the cords (injury risks aspiration).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('852b0f18-5479-553e-ba2c-2d7c507a00eb', 'bab63b51-b37d-51b4-89f3-e656110fce7e', 'A', 'Hypoglossal nerve', false, 0),
  ('e88fc2bb-946f-5f93-9c7b-662cd9fc30e0', 'bab63b51-b37d-51b4-89f3-e656110fce7e', 'B', 'Glossopharyngeal nerve', false, 1),
  ('8e4e0044-053d-591b-8778-164f84b309da', 'bab63b51-b37d-51b4-89f3-e656110fce7e', 'C', 'External branch of the superior laryngeal nerve', true, 2),
  ('425152e4-53cc-56bd-96a8-de044273788e', 'bab63b51-b37d-51b4-89f3-e656110fce7e', 'D', 'Internal branch of the superior laryngeal nerve', false, 3),
  ('8e4ff59d-4577-565d-b08f-cf980ab136b9', 'bab63b51-b37d-51b4-89f3-e656110fce7e', 'E', 'Recurrent laryngeal nerve', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6ae589ae-c5d1-5654-8c0a-b62362487e6c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 30 year old man has a deep laceration on the front of his wrist. He cannot oppose his thumb to his little finger and has lost sensation over the palmar aspect of the thumb, index and middle fingers. Which nerve has been injured?', 'Median nerve injury at the wrist paralyses the thenar muscles (loss of opposition and abduction of the thumb, with thenar wasting later) and causes sensory loss over the radial three and a half digits. The palmar cutaneous branch arises before the carpal tunnel, so palm sensation may be preserved in carpal tunnel syndrome but not in a laceration above it. The anterior interosseous nerve is purely motor (it causes a weak ''OK'' sign).', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
