  ('d8388483-2510-5782-b40b-c673f2869f47', '3e114500-aae0-59f8-b4bb-fd9c10c15590', 'B', 'Parietal cells', true, 1),
  ('72949e61-f575-5754-96cc-92e651837a75', '3e114500-aae0-59f8-b4bb-fd9c10c15590', 'C', 'Chief cells', false, 2),
