  ('af9bc71e-7232-5e81-841d-d188018badc3', '3e114500-aae0-59f8-b4bb-fd9c10c15590', 'E', 'Enterochromaffin-like cells', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('338e3a40-ba11-540e-b5fc-f2a7287330f8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 58 year old man''s arterial blood gas on air shows pH 7.30, PaCO2 3.1 kPa, bicarbonate 11 mmol/L. His sodium is 140, chloride 115 mmol/L. Which is the SINGLE most likely cause?', 'The anion gap is Na - (Cl + HCO3) = 140 - (115 + 11) = 14 mmol/L, which is normal (about 8-16). This is a normal anion gap (hyperchloraemic) metabolic acidosis with respiratory compensation. Causes are loss of bicarbonate (diarrhoea, fistulae, ureterosigmoidostomy), renal tubular acidosis, acetazolamide and Addison''s disease. DKA, lactic acidosis, methanol and salicylates cause a raised anion gap.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
