  ('efd859e2-02b3-5a96-803e-3da075e9ba7f', '451cb745-01dc-5bf5-b723-e61e6f5e1306', 'A', 'Serum IgE', false, 0),
  ('aff047c9-e025-5894-a234-fb243672dd89', '451cb745-01dc-5bf5-b723-e61e6f5e1306', 'B', 'Serum complement C4', true, 1),
  ('95504c43-5ed0-588e-8122-94b1b5f68454', '451cb745-01dc-5bf5-b723-e61e6f5e1306', 'C', 'Serum tryptase', false, 2),
  ('66ef02ae-2f52-5bbe-8291-e56d15efecb6', '451cb745-01dc-5bf5-b723-e61e6f5e1306', 'D', 'Skin prick testing', false, 3),
