  ('a3e961bc-d372-5ce5-b1d0-f197d215c7b1', '7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'A', 'Skin', false, 0),
  ('6c56ca6a-290a-5eca-8687-2715703fca1e', '7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'B', 'Loose areolar tissue', false, 1),
  ('a2711d0f-ca81-5273-ae56-2dab614dc0c4', '7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'C', 'Aponeurosis (galea aponeurotica)', false, 2),
  ('e912cef8-afea-5f2a-b858-8bf372bf561f', '7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'D', 'Dense connective tissue', true, 3),
  ('e0d2e138-bfc3-5f78-8cb2-912721705bf2', '7ff66287-0cc9-5b0c-b5ac-7d8d88b3373c', 'E', 'Pericranium', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000033', 'sba', 'A 48 year old woman needs a lumbar puncture. Which landmark is used to find the L3/L4 or L4/L5 interspace?', 'The intercristal (Tuffier''s) line crosses the spinous process of L4 or the L4/L5 interspace. Lumbar puncture is done at L3/L4 or L4/L5, below the end of the spinal cord (conus medullaris, at about L1/L2 in adults and lower in neonates, around L3). The inferior angle of the scapula is at about T7.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('24004291-c108-57cd-a824-91ed412d15e0', '6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'A', 'The posterior superior iliac spines', false, 0),
  ('5a5df501-30e8-5f70-a558-f26bc2130827', '6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'B', 'The 12th rib', false, 1),
  ('eee57b0f-b277-59d4-99fd-0b46a2b1efea', '6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'C', 'The inferior angles of the scapulae', false, 2),
  ('69427eb0-f9e5-5911-b29f-1da634720905', '6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'D', 'The umbilicus', false, 3),
  ('581d8a51-ccca-5f78-8871-b7f92bb29c46', '6bc0e30e-9e95-51df-ad24-85b8a2a45c24', 'E', 'A line joining the highest points of the iliac crests (Tuffier''s line)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('f83cb1c3-e080-5145-b49e-6715300dc881', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 58 year old woman has been treated for early oestrogen receptor-positive breast cancer with surgery, and is due to start an aromatase inhibitor. Which investigation should be arranged before starting it?', 'Aromatase inhibitors (anastrozole, letrozole, exemestane) block peripheral oestrogen production and speed up bone loss, increasing osteoporosis and fracture risk. NICE recommends a baseline DEXA scan, with calcium/vitamin D and bisphosphonates if needed. Adjuvant bisphosphonates (zoledronic acid) are also offered to postmenopausal women at higher risk of recurrence. Tamoxifen, not aromatase inhibitors, raises endometrial cancer risk. Trastuzumab needs cardiac monitoring.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('af044bd4-0d1f-5c17-b0ee-a7c461f960f7', 'f83cb1c3-e080-5145-b49e-6715300dc881', 'A', 'Echocardiogram', false, 0),
  ('5f6e9d53-e163-5817-9e10-cd09fc7aa49f', 'f83cb1c3-e080-5145-b49e-6715300dc881', 'B', 'Retinal screening', false, 1),
  ('be25736a-e127-5bbc-9131-d98bb9efd788', 'f83cb1c3-e080-5145-b49e-6715300dc881', 'C', 'Endometrial ultrasound', false, 2),
  ('ac5a83a9-9f94-57ac-8abe-4623a4bfb76b', 'f83cb1c3-e080-5145-b49e-6715300dc881', 'D', 'DEXA scan for bone mineral density', true, 3),
  ('ff2572a8-cee5-53b5-a726-42ac2f851224', 'f83cb1c3-e080-5145-b49e-6715300dc881', 'E', 'Pulmonary function tests', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 28 year old woman has a non-tender, smooth, mobile 2 cm breast lump. Triple assessment shows a fibroadenoma. Six months later she returns as it has grown quickly to 6 cm. Core biopsy shows a ''leaf-like'' architecture with stromal overgrowth. What is the SINGLE most likely diagnosis?', 'Phyllodes tumours are fibroepithelial tumours that look like fibroadenomas but grow rapidly and have a leaf-like architecture with cellular stroma. They can be benign, borderline or malignant, and can recur locally. Treatment is wide local excision with clear margins (at least 1 cm). Axillary surgery is not needed because spread to the lymph nodes is rare.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bb5631af-1194-58ed-9e5b-559adfdb7f64', 'bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'A', 'Phyllodes tumour', true, 0),
  ('9f329ec8-928e-5b7b-84d9-b509edfbc4d4', 'bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'B', 'Giant fibroadenoma', false, 1),
  ('36095ffa-d644-5056-851a-ca4e7f01cd49', 'bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'C', 'Invasive ductal carcinoma', false, 2),
  ('ec795ce5-32d9-55a3-a13e-763c362a6358', 'bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'D', 'Breast cyst', false, 3),
  ('2e6054d4-0d8a-5b16-ac14-71bef99b9687', 'bd8ec56c-b7b4-54f7-aafc-18a86db470cd', 'E', 'Lipoma', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000022', 'sba', 'A 50 year old woman attends routine breast screening. The mammogram shows clustered microcalcifications. Biopsy shows ductal carcinoma in situ (DCIS) that has not invaded the basement membrane. Which statement is CORRECT?', 'DCIS is a non-obligate precursor of invasive cancer, often found as microcalcification at screening. It is treated by wide local excision (with radiotherapy for most) or mastectomy for extensive disease. Sentinel node biopsy is only considered with mastectomy or high-grade/extensive DCIS, and axillary clearance is not routine. Chemotherapy is not used. Endocrine therapy may be offered for ER-positive DCIS.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('69e55b21-8fc0-5071-bc38-0fe68ad855b8', 'e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'A', 'It is always treated with chemotherapy', false, 0),
  ('f35f107b-e0b5-5d45-bb0d-5bbb626a206b', 'e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'B', 'It cannot progress to invasive cancer', false, 1),
  ('840787b7-8f94-53ef-80df-4c84d8288806', 'e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'C', 'It is a non-invasive cancer treated with surgery, often followed by radiotherapy after breast-conserving surgery', true, 2),
  ('b4404019-3cdb-518e-be37-790dae05d4d4', 'e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'D', 'It does not appear on mammography', false, 3),
  ('abc8fee3-7201-5a27-ae1e-d81b89ee090d', 'e69e9adb-cdc9-59ed-b8f3-f395aed1e22f', 'E', 'It needs routine axillary node clearance', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('32469eed-76f4-5708-a76b-c801128e8bd4', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 66 year old man with metastatic prostate cancer has new back pain. He then develops leg weakness and urinary retention. MRI confirms metastatic spinal cord compression at T10. What is the SINGLE most appropriate immediate drug treatment?', 'In metastatic spinal cord compression with neurological deficit, NICE (NG234) recommends dexamethasone 16 mg straight away (with gastroprotection, and monitoring of glucose), then definitive treatment within 24 hours: surgery (decompression with stabilisation) or radiotherapy. He should be nursed flat if there is spinal instability. Early treatment preserves mobility and continence.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('34cbae14-9eca-5dc2-8f7f-e929351359e0', '32469eed-76f4-5708-a76b-c801128e8bd4', 'A', 'IV zoledronic acid only', false, 0),
  ('5bc24c1a-bcb6-5a41-a459-22b18b535ab1', '32469eed-76f4-5708-a76b-c801128e8bd4', 'B', 'Dexamethasone 16 mg orally (or IV), with a PPI', true, 1),
  ('cd33e0b9-f277-5b7d-8b1d-1b2263eef358', '32469eed-76f4-5708-a76b-c801128e8bd4', 'C', 'Morphine only', false, 2),
  ('a9e73a64-0381-5270-9b89-6a81a9201a0b', '32469eed-76f4-5708-a76b-c801128e8bd4', 'D', 'IV furosemide', false, 3),
  ('b5c7be11-4b05-58cb-8d1f-21309e50adf1', '32469eed-76f4-5708-a76b-c801128e8bd4', 'E', 'Oral prednisolone 5 mg', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('daf7b600-86b8-5901-9a19-a21c190c9d43', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 25 year old man has a painless, firm swelling of his left testis. His serum alpha-fetoprotein is normal, beta-hCG is mildly raised, and LDH is normal. Scrotal ultrasound shows a homogeneous hypoechoic mass. What is the SINGLE most likely diagnosis?', 'Seminomas are the most common testicular germ cell tumour and peak at age 30-40. AFP is never raised in pure seminoma (a raised AFP means a non-seminomatous component). hCG may be mildly raised. Non-seminomatous tumours (teratoma, yolk sac, choriocarcinoma) occur in younger men and often raise AFP and/or hCG. Treatment is radical inguinal orchidectomy. Seminomas are very radiosensitive.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('0db353f8-acf2-5699-aba7-707d05bfb5f8', 'daf7b600-86b8-5901-9a19-a21c190c9d43', 'A', 'Yolk sac tumour', false, 0),
  ('291ba758-b802-5951-8708-13b8d3f7b6d2', 'daf7b600-86b8-5901-9a19-a21c190c9d43', 'B', 'Teratoma', false, 1),
  ('61124073-f0be-5105-868d-503548299d20', 'daf7b600-86b8-5901-9a19-a21c190c9d43', 'C', 'Epididymal cyst', false, 2),
  ('e41bc03e-a048-5760-ad4c-34e6b7ba1279', 'daf7b600-86b8-5901-9a19-a21c190c9d43', 'D', 'Seminoma', true, 3),
  ('5bf1643b-97e6-518c-9a4a-99dfd88cd9e3', 'daf7b600-86b8-5901-9a19-a21c190c9d43', 'E', 'Leydig cell tumour', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('4bd28f8b-bcdd-50cd-9346-808397b6f967', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 59 year old woman has abdominal bloating and early satiety for 2 months. Her serum CA-125 is 180 U/mL. What is the SINGLE most appropriate next investigation?', 'NICE (CG122) says that for women with persistent bloating, early satiety, pelvic or abdominal pain or urinary symptoms, measure CA-125. If it is 35 IU/mL or more, arrange an abdominal and pelvic ultrasound. If the ultrasound suggests ovarian cancer, refer urgently on the suspected cancer pathway. A risk of malignancy index (RMI) combining CA-125, ultrasound findings and menopausal status guides management.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('d3fdf91d-d7cf-584e-848d-128d6f02b2c6', '4bd28f8b-bcdd-50cd-9346-808397b6f967', 'A', 'Colonoscopy', false, 0),
  ('d0688c8f-9332-5b10-8556-2709a740e533', '4bd28f8b-bcdd-50cd-9346-808397b6f967', 'B', 'Ultrasound of the abdomen and pelvis', true, 1),
  ('a4e84414-d431-5ec8-a0d7-833c6387869d', '4bd28f8b-bcdd-50cd-9346-808397b6f967', 'C', 'Upper GI endoscopy', false, 2),
  ('2c53711e-51b5-5766-9137-0da3ffc92680', '4bd28f8b-bcdd-50cd-9346-808397b6f967', 'D', 'Repeat CA-125 in 3 months', false, 3),
  ('0b7be2a1-339b-5005-8f24-99d968ade4ad', '4bd28f8b-bcdd-50cd-9346-808397b6f967', 'E', 'Serum CEA', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000024', 'sba', 'A 70 year old man had chemotherapy for high-grade non-Hodgkin lymphoma 2 days ago. He now has palpitations and reduced urine output. Bloods show potassium 6.6 mmol/L, phosphate 2.8 mmol/L, calcium 1.7 mmol/L, urate 720 µmol/L and creatinine 290 µmol/L. Which drug should have been given before chemotherapy to reduce this risk in a high-risk patient?', 'This is tumour lysis syndrome: hyperkalaemia, hyperphosphataemia, hypocalcaemia, hyperuricaemia and AKI after cytotoxic treatment of a bulky, chemosensitive tumour. Prevention is with IV hydration plus allopurinol (low/intermediate risk) or rasburicase (high risk). Rasburicase is a recombinant urate oxidase that breaks down existing uric acid. It is contraindicated in G6PD deficiency. Now treat the hyperkalaemia urgently.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c4739f39-8b5d-5be6-9ac2-79c2939086f8', '2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'A', 'Furosemide', false, 0),
  ('c0e5cc1a-e7d2-5e92-b1ae-c5c62d633653', '2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'B', 'Rasburicase', true, 1),
  ('adc1eab7-6b7c-5871-b2de-81183484ba9a', '2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'C', 'Sodium bicarbonate', false, 2),
  ('5480f056-a12c-5bcc-969e-4c4712c8e6c9', '2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'D', 'Calcium gluconate', false, 3),
  ('3469bdef-f0e4-5ba1-b4c9-2db80e282343', '2806e2bd-e04a-5bd0-9d37-e872ec5d3f01', 'E', 'Allopurinol only after chemotherapy', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 30 year old man had a blunt head injury and was briefly knocked out. He then had a lucid interval, but is now drowsy with a dilated left pupil. CT head shows a biconvex (lentiform) hyperdense collection that does not cross suture lines. Which vessel is MOST likely to be the source?', 'An extradural haematoma is usually caused by a temporal bone fracture tearing the middle meningeal artery. It is lentiform because it is limited by dural attachments at the sutures. The classic course is a lucid interval followed by rapid deterioration. Subdural haematomas come from torn bridging veins and are crescent-shaped, crossing sutures. Urgent neurosurgical evacuation is needed.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('6a4e4479-97ba-5e2d-a64c-461ef3b1ca66', 'e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'A', 'Superior sagittal sinus', false, 0),
  ('bc5d1589-5685-5e15-b042-8b3c111ec29c', 'e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'B', 'Middle meningeal artery', true, 1),
  ('9c2f4d56-a75a-51af-9c06-8c44f86078c1', 'e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'C', 'Middle cerebral artery', false, 2),
  ('3fbc5db8-c10a-50ee-bfff-06d09b6fd694', 'e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'D', 'Bridging veins', false, 3),
  ('2bc1513f-1787-5dd3-8993-81000cb8327f', 'e67d9c0c-8029-52ae-b977-cb09c3d4c039', 'E', 'Posterior communicating artery', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('72f78754-e5c3-503a-8405-2aee57f30f4b', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 27 year old woman who is 10 weeks pregnant has suspected pulmonary embolism. Her chest X-ray is normal and she has no leg symptoms. Which imaging is generally preferred to confirm the diagnosis?', 'In pregnancy, a raised D-dimer is expected, so it is not used to exclude PE. If there are leg symptoms, do Doppler ultrasound first. If the chest X-ray is normal, a V/Q (or perfusion-only) scan is often preferred: it gives a lower radiation dose to maternal breast tissue (CTPA gives a slightly lower fetal dose). The choice should be discussed with the woman. Start LMWH while waiting for imaging if there will be any delay.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9fcc9c57-3cbf-5c1e-b6a3-c1de0602522f', '72f78754-e5c3-503a-8405-2aee57f30f4b', 'A', 'Plain abdominal X-ray', false, 0),
  ('aadfb703-329f-5d07-a170-7ff87a20d5f7', '72f78754-e5c3-503a-8405-2aee57f30f4b', 'B', 'CT pulmonary angiogram is always mandatory', false, 1),
  ('e781e693-e43c-54cc-be21-4fcf14c40556', '72f78754-e5c3-503a-8405-2aee57f30f4b', 'C', 'Ventilation/perfusion (V/Q) or perfusion (Q) scan', true, 2),
  ('a4989fed-23da-5e0f-98f0-f915a12050aa', '72f78754-e5c3-503a-8405-2aee57f30f4b', 'D', 'MRI of the chest', false, 3),
  ('7c3004a3-7f66-53d7-ab28-2da5b7cb34b0', '72f78754-e5c3-503a-8405-2aee57f30f4b', 'E', 'D-dimer alone to exclude PE', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 70 year old man with an eGFR of 25 mL/min/1.73m² needs a contrast-enhanced CT. Which measure is MOST important to reduce the risk of contrast-associated acute kidney injury?', 'NICE and the Royal College of Radiologists recommend IV hydration with isotonic fluids for patients at higher risk (eGFR under 30, or AKI) having IV iodinated contrast. Consider stopping nephrotoxic drugs temporarily, and withhold metformin according to local guidance. Use the lowest effective contrast dose. N-acetylcysteine has not shown consistent benefit.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('fd1c63a2-81c7-5522-bd27-9e20eb5c4503', '9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'A', 'Doubling his metformin dose', false, 0),
  ('50c88830-9de9-54b2-a8fd-f7452353726c', '9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'B', 'IV volume expansion with 0.9% sodium chloride (or isotonic bicarbonate) before and after the scan', true, 1),
  ('f2c38e2a-6cab-5f66-bf77-75026427ab16', '9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'C', 'Oral N-acetylcysteine alone', false, 2),
  ('35a8eaad-af8c-5d28-ae61-9eb17e136ab2', '9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'D', 'Giving IV furosemide before contrast', false, 3),
  ('06659429-0652-509b-b51f-d5520da96c73', '9a375b5a-1dd3-524e-a44d-89f3f0d00d1a', 'E', 'Using twice the usual contrast volume for better images', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('dba788d3-72be-5207-a196-a8eef4405077', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000025', 'sba', 'A 68 year old man has acute abdominal pain and rigidity. An erect chest X-ray is requested. What finding would MOST strongly support perforation of a hollow viscus?', 'Free gas under the hemidiaphragms on an erect chest X-ray suggests perforation (such as a perforated peptic ulcer or diverticulum). The patient should be upright for at least 10 minutes before the film. Note that a normal chest X-ray does not exclude perforation: CT is more sensitive. Gas can also be present after recent laparotomy or laparoscopy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
