insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('d68bd342-a530-50e3-baf8-121d6beca0e8', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 55 year old woman with septic shock has a MAP of 58 mmHg despite 30 mL/kg of IV crystalloid. Her lactate is 5 mmol/L. Which is the first-line vasopressor?', 'Surviving Sepsis guidelines recommend noradrenaline as the first-line vasopressor to target a MAP of 65 mmHg or more. It is ideally given through a central line (peripheral administration is acceptable short-term through a large vein). Vasopressin can be added next, and adrenaline after that. Dobutamine is used for low cardiac output with myocardial dysfunction. Hydrocortisone is considered if vasopressor needs are ongoing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c8f6d235-43f1-5e0e-a295-2b93ffb04334', 'd68bd342-a530-50e3-baf8-121d6beca0e8', 'A', 'Adrenaline', false, 0),
  ('b25ce4c2-de40-5f4e-9a77-39960dbc4ccd', 'd68bd342-a530-50e3-baf8-121d6beca0e8', 'B', 'Dopamine', false, 1),
  ('27027450-2093-5642-a879-3107bb027c69', 'd68bd342-a530-50e3-baf8-121d6beca0e8', 'C', 'Isoprenaline', false, 2),
  ('c8c9c32d-542c-5c58-ad9c-e6ce896553a6', 'd68bd342-a530-50e3-baf8-121d6beca0e8', 'D', 'Dobutamine', false, 3),
  ('6584c4a1-5064-56fa-8800-41d5ea0cd7d4', 'd68bd342-a530-50e3-baf8-121d6beca0e8', 'E', 'Noradrenaline', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('5cbab439-5bdf-5644-a050-b04ae12df260', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 40 year old man is ventilated on intensive care for ARDS. His PaO2 is 9 kPa on FiO2 0.6. What is his PaO2/FiO2 (P/F) ratio, and how is the ARDS classified (Berlin)?', 'P/F = 9 / 0.6 = 15 kPa (15 x 7.5 = about 113 mmHg). Berlin definition (with PEEP of 5 or more): mild 200-300 mmHg (26.7-40 kPa); moderate 100-200 mmHg (13.3-26.7 kPa); severe 100 mmHg or less (13.3 kPa or less). Management is lung-protective ventilation (6 mL/kg predicted body weight, plateau pressure 30 cmH2O or less), with prone positioning for moderate-severe cases.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e55a980a-04cc-54fd-978a-e43bb9888e42', '5cbab439-5bdf-5644-a050-b04ae12df260', 'A', '5.4 kPa - severe ARDS', false, 0),
  ('b3c0384b-44c6-5790-95fb-9949196d3c8d', '5cbab439-5bdf-5644-a050-b04ae12df260', 'B', '15 kPa (about 113 mmHg) - moderate ARDS', true, 1),
  ('e003500e-c2a7-5cf7-a457-5f46af3a3064', '5cbab439-5bdf-5644-a050-b04ae12df260', 'C', '15 kPa - mild ARDS', false, 2),
  ('99777015-750f-56bf-8444-9dc44d78d205', '5cbab439-5bdf-5644-a050-b04ae12df260', 'D', '25 kPa - mild ARDS', false, 3),
  ('79d17695-8a6a-5f06-8c6a-79f33b21b681', '5cbab439-5bdf-5644-a050-b04ae12df260', 'E', '54 kPa - no ARDS', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ec243f25-2b17-5a22-92e4-614f5413fb69', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 75 year old man is on intensive care with sepsis. On day 3 he becomes agitated, then drowsy, with fluctuating attention and disorganised thinking. Which is the BEST bedside tool to detect this problem on ICU?', 'ICU delirium is common and linked to higher mortality and long-term cognitive impairment. CAM-ICU (or the ICDSC) is validated for ventilated and non-verbal patients. It assesses acute change or fluctuation, inattention, altered level of consciousness and disorganised thinking. Management: find and treat causes, reduce sedatives and anticholinergics, re-orientate, support sleep, and mobilise early.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('707a7efd-6ec5-5ed7-be9f-dc92ea1750ee', 'ec243f25-2b17-5a22-92e4-614f5413fb69', 'A', 'Confusion Assessment Method for the ICU (CAM-ICU)', true, 0),
  ('e65092f2-3725-5a82-b52e-a51cc40bad86', 'ec243f25-2b17-5a22-92e4-614f5413fb69', 'B', 'Abbreviated Mental Test Score 10', false, 1),
  ('241ab0c6-1806-5030-afc7-5593421308df', 'ec243f25-2b17-5a22-92e4-614f5413fb69', 'C', 'Mini-Mental State Examination', false, 2),
  ('71f3587c-8cf6-5f2b-a7a9-78f8030596d2', 'ec243f25-2b17-5a22-92e4-614f5413fb69', 'D', 'Glasgow Coma Scale only', false, 3),
  ('6ebf06e4-b110-579c-9792-71c974b636b2', 'ec243f25-2b17-5a22-92e4-614f5413fb69', 'E', 'PHQ-9', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 70 kg man on ICU after a road traffic collision has a BP of 80/50 mmHg and HR 52 bpm with warm peripheries. He has a cervical spine injury at C5 with loss of motor function below that level. What is the SINGLE most likely type of shock?', 'Cervical or high thoracic cord injury disrupts sympathetic outflow, causing vasodilatation (hypotension with warm peripheries) and unopposed vagal tone (bradycardia). This is neurogenic shock. Haemorrhage must still be excluded in a trauma patient. Treatment is fluids, vasopressors and atropine for bradycardia. Spinal shock is a different thing: temporary loss of reflexes below the lesion.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('7203f9da-b542-5f4c-8b40-49496427af32', 'fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'A', 'Anaphylactic shock', false, 0),
  ('1ef5c3ec-b2b2-58a3-9588-a77f06325965', 'fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'B', 'Hypovolaemic shock', false, 1),
  ('ae13391c-c43c-598f-b00d-585deb96e05f', 'fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'C', 'Cardiogenic shock', false, 2),
  ('8dfb7738-2bb5-5c6e-ad1b-56955b29a1e0', 'fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'D', 'Neurogenic shock', true, 3),
  ('39e9e2b1-7bea-5ae0-8b96-ab5448be3b35', 'fbac1acf-dd1b-5b0b-8bb6-7b950e852ae9', 'E', 'Obstructive shock', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000035', 'sba', 'A 66 year old man on ICU has an arterial blood gas showing pH 7.48, PaCO2 6.6 kPa and bicarbonate 36 mmol/L. He has had a nasogastric tube on free drainage for 4 days with large aspirates. What is the acid-base disorder?', 'A high pH and high bicarbonate mean metabolic alkalosis. The raised PaCO2 is compensatory hypoventilation. Losing gastric acid (vomiting or NG aspiration) causes hypochloraemic, hypokalaemic metabolic alkalosis, maintained by volume depletion. Treat with 0.9% sodium chloride and potassium replacement.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('360987c8-4f6b-5439-a8fe-776d7b282e25', 'b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'A', 'Metabolic alkalosis with respiratory compensation', true, 0),
  ('885e4721-d29a-5d85-ab68-5380dd2632e4', 'b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'B', 'Metabolic acidosis', false, 1),
  ('67dffd52-f71a-524e-9086-9b31ab7afdfa', 'b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'C', 'Respiratory alkalosis', false, 2),
  ('4f913caa-0e9b-5096-9491-fa2ad37a5748', 'b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'D', 'Mixed respiratory and metabolic acidosis', false, 3),
  ('11b3aead-529b-5664-a09f-ddeca42eca61', 'b5d09c37-1c6d-5de4-9da2-5e2534ce6eb6', 'E', 'Respiratory acidosis with renal compensation', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('6200fe07-64e1-5104-a217-979cae80f4ed', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 66 year old woman with pancreatic cancer has nausea and vomiting caused by gastric stasis (early satiety, large-volume vomits, relief after vomiting). She has no bowel obstruction. Which antiemetic is MOST appropriate?', 'Metoclopramide is a prokinetic (it works on D2 and 5-HT4 receptors) and is first-line for gastric stasis or impaired gastric emptying. It should be avoided in complete bowel obstruction with colic, and in Parkinson''s disease. Haloperidol is first-line for chemical or metabolic causes (opioids, hypercalcaemia, renal failure). Cyclizine is for raised intracranial pressure and vestibular causes.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
