  ('d6255f49-1be4-5e41-a34c-6088c9ba4c38', '6200fe07-64e1-5104-a217-979cae80f4ed', 'A', 'Ondansetron', false, 0),
  ('2dbf701d-8731-59f8-bf92-0a2c95c5746a', '6200fe07-64e1-5104-a217-979cae80f4ed', 'B', 'Haloperidol', false, 1),
  ('1a302e84-cef7-5aa3-89ec-b33e25a42957', '6200fe07-64e1-5104-a217-979cae80f4ed', 'C', 'Metoclopramide', true, 2),
  ('53c37703-fb7c-52be-9ee3-d9c52a9bf5a8', '6200fe07-64e1-5104-a217-979cae80f4ed', 'D', 'Cyclizine', false, 3),
  ('f2b1d8a9-b52a-543f-a303-a44e6746bbc4', '6200fe07-64e1-5104-a217-979cae80f4ed', 'E', 'Levomepromazine', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3e250a53-3bba-56f4-b80d-fc71e3aab498', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 58 year old man with metastatic prostate cancer takes modified-release morphine 60 mg twice daily. His pain is well controlled, but he now cannot swallow. He is to have a subcutaneous syringe driver over 24 hours. What dose of subcutaneous morphine sulfate should be prescribed?', 'The total oral morphine dose is 120 mg/24 hours. Subcutaneous morphine is about twice as potent as oral morphine, so divide by 2, giving 60 mg/24 hours. The breakthrough dose is one-sixth of the 24-hour dose (here 10 mg SC as needed). If the patient has renal impairment, consider oxycodone or alfentanil. Always check conversions against local guidance.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
