  ('76a071b6-0d31-5a2f-8cd4-2c7d696424a9', '3e250a53-3bba-56f4-b80d-fc71e3aab498', 'A', '20 mg over 24 hours', false, 0),
  ('588b0298-8148-5016-b829-447c520159b5', '3e250a53-3bba-56f4-b80d-fc71e3aab498', 'B', '40 mg over 24 hours', false, 1),
  ('ab650827-2030-5755-8e1a-eb01c85411aa', '3e250a53-3bba-56f4-b80d-fc71e3aab498', 'C', '60 mg over 24 hours', true, 2),
  ('13099440-e149-5be6-990a-233ead9f34d6', '3e250a53-3bba-56f4-b80d-fc71e3aab498', 'D', '120 mg over 24 hours', false, 3),
  ('48772d7d-f913-5c1f-b0d3-6c5abfee7411', '3e250a53-3bba-56f4-b80d-fc71e3aab498', 'E', '240 mg over 24 hours', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b12e271c-947a-5cac-b5e3-a69559d22242', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000017', 'sba', 'A 63 year old man with a brain tumour, in the last days of life, has had a seizure lasting over 5 minutes at home. He cannot swallow. Which is MOST appropriate as first-line treatment at home?', 'In palliative care, buccal (or SC) midazolam is first-line for a seizure lasting more than 5 minutes, as it is easy to give at home. Rectal diazepam is an alternative. If seizures continue to be a risk when the person cannot swallow, a continuous subcutaneous infusion of midazolam (or levetiracetam SC, off-label) can be used in a syringe driver.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('e90da972-c4af-59a4-9d01-8876af120383', 'b12e271c-947a-5cac-b5e3-a69559d22242', 'A', 'Oral levetiracetam', false, 0),
  ('108e98b0-98d2-5932-b24b-94aadda0ad4d', 'b12e271c-947a-5cac-b5e3-a69559d22242', 'B', 'Buccal midazolam (or subcutaneous midazolam)', true, 1),
  ('f566a6d2-0b15-5032-a1d8-60a067ccf497', 'b12e271c-947a-5cac-b5e3-a69559d22242', 'C', 'IV lorazepam', false, 2),
  ('6c383406-4c10-5b96-be1e-d0094c32bf67', 'b12e271c-947a-5cac-b5e3-a69559d22242', 'D', 'Rectal paracetamol', false, 3),
  ('f2c59049-cfad-55ef-88ed-4b1e266c760a', 'b12e271c-947a-5cac-b5e3-a69559d22242', 'E', 'Oral phenytoin', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('14a3aca7-46b6-5b03-981e-66e5358d391c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 30 year old woman is having a laparoscopic cholecystectomy. She had severe nausea and vomiting after a previous anaesthetic, she does not smoke, and opioids will be needed afterwards. What is the BEST approach to reduce postoperative nausea and vomiting?', 'Apfel risk factors are female sex, non-smoker, previous PONV or motion sickness, and postoperative opioids. She has all 4 (about 80% risk). Give combination prophylaxis using drugs with different actions: dexamethasone at induction, a 5-HT3 antagonist at the end, and consider TIVA with propofol and reduced volatile/nitrous oxide use.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c089a67b-4468-5407-916e-08604853740b', '14a3aca7-46b6-5b03-981e-66e5358d391c', 'A', 'A single dose of metoclopramide only', false, 0),
  ('be2010f2-50cd-5268-8909-57a1c75a6c67', '14a3aca7-46b6-5b03-981e-66e5358d391c', 'B', 'No prophylaxis unless she vomits', false, 1),
  ('3329b062-4def-52d4-8d6e-067545377e73', '14a3aca7-46b6-5b03-981e-66e5358d391c', 'C', 'Risk-stratified multimodal prophylaxis (e.g. dexamethasone at induction plus ondansetron at the end)', true, 2),
  ('d1acc02d-b1d4-5466-87aa-d2280e34564e', '14a3aca7-46b6-5b03-981e-66e5358d391c', 'D', 'Avoid all analgesia', false, 3),
  ('af97284c-df6d-58e7-bcf8-30fe89cdf268', '14a3aca7-46b6-5b03-981e-66e5358d391c', 'E', 'Use high-dose nitrous oxide', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 72 year old man is on the second day after a laparotomy. He has a urine output of 15 mL/hour for 4 hours, HR 108 bpm, BP 98/62 mmHg and cool peripheries. His bladder scan shows 50 mL. What is the SINGLE most appropriate next step?', 'Oliguria with tachycardia, low BP and poor perfusion after surgery suggests hypovolaemia (third-space losses, bleeding). The bladder scan excludes retention. NICE fluid guidance recommends a 500 mL crystalloid bolus (250 mL if at risk of overload, such as with heart failure) over less than 15 minutes, then reassess. Diuretics in a hypovolaemic patient would make the AKI worse. ''Renal dose'' dopamine is not effective.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9f732dd1-3f80-5609-98b4-7e288f70c147', '2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'A', 'IV furosemide 40 mg', false, 0),
  ('74229f14-0675-5db3-891d-8efcc521d61d', '2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'B', 'Fluid-restrict to 1 L/day', false, 1),
  ('c05f1f00-b04c-5e5c-84bc-ee77cc2dd4f5', '2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'C', 'Insert a suprapubic catheter', false, 2),
  ('f08de4f2-eea8-5929-897d-3ca14dcc017e', '2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'D', 'Start IV dopamine at renal dose', false, 3),
  ('82ce74eb-f434-5096-8096-ba162c073b9a', '2bf3770d-c550-5c8e-9ffe-b23e5b488bff', 'E', 'Give a 250-500 mL IV crystalloid bolus over 15 minutes and reassess', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7f591869-d83f-5d7c-ae82-f08b34c1c085', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 55 year old man is having an elective hernia repair. He has type 1 diabetes treated with a basal-bolus regimen. He is on a morning list and will miss only one meal. What is the SINGLE most appropriate advice about his insulin?', 'In type 1 diabetes, basal insulin must never be stopped completely because of the risk of DKA. For a short starve (one missed meal), the CPOC/JBDS guidance is to continue basal insulin (reduce by 20% if once daily long-acting), omit the bolus insulin for the missed meal, and monitor capillary glucose (target 6-12 mmol/L). A variable-rate IV insulin infusion is used for longer starvation (missing 2 or more meals) or poor control.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bd2b21f8-2aee-5a7f-b06c-0987638ef71d', '7f591869-d83f-5d7c-ae82-f08b34c1c085', 'A', 'Continue his long-acting basal insulin, often at 80% of the usual dose, and omit his breakfast rapid-acting insulin', true, 0),
  ('3855d94e-68eb-5d83-b68c-6b18310001f0', '7f591869-d83f-5d7c-ae82-f08b34c1c085', 'B', 'Stop all insulin the day before surgery', false, 1),
  ('a4ba99ee-c75d-5f65-b55e-6e5963714658', '7f591869-d83f-5d7c-ae82-f08b34c1c085', 'C', 'Double his basal insulin', false, 2),
  ('4e9f0533-9ce2-5391-be2b-58d234ce8e5c', '7f591869-d83f-5d7c-ae82-f08b34c1c085', 'D', 'Take his usual rapid-acting insulin with no breakfast', false, 3),
  ('513d35e2-8853-59fb-9d44-3bd0c997405a', '7f591869-d83f-5d7c-ae82-f08b34c1c085', 'E', 'Start a sliding scale the night before for every patient', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('b18462f9-5669-5b27-bc34-7543c31dc069', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 22 year old man has general anaesthesia with suxamethonium and sevoflurane. Twenty minutes later his end-tidal CO2 rises sharply, he develops tachycardia and masseter rigidity, and his temperature is rising. What is the SINGLE most likely diagnosis?', 'Malignant hyperthermia is an autosomal dominant (RYR1) disorder triggered by volatile anaesthetics and suxamethonium. Uncontrolled release of calcium in skeletal muscle causes rising ETCO2 (the earliest sign), tachycardia, rigidity, hyperthermia, hyperkalaemia, acidosis and rhabdomyolysis. Stop triggers, give IV dantrolene, cool, and treat hyperkalaemia. The patient and family need referral for testing.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('c292acf1-5b73-5530-bf79-ea898d8b636f', 'b18462f9-5669-5b27-bc34-7543c31dc069', 'A', 'Anaphylaxis', false, 0),
  ('a7067583-9ad9-5900-8794-1e03944226f7', 'b18462f9-5669-5b27-bc34-7543c31dc069', 'B', 'Serotonin syndrome', false, 1),
  ('bcc2618e-baef-5293-9c3c-cca06626c73c', 'b18462f9-5669-5b27-bc34-7543c31dc069', 'C', 'Neuroleptic malignant syndrome', false, 2),
  ('75e91d86-b8d9-5b3b-b0c7-460d332c31e4', 'b18462f9-5669-5b27-bc34-7543c31dc069', 'D', 'Malignant hyperthermia', true, 3),
  ('9b52cca5-2c1f-5fbb-86e2-351ecc41455c', 'b18462f9-5669-5b27-bc34-7543c31dc069', 'E', 'Thyroid storm', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('9f2e7279-b377-5bba-afb8-094a92394242', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 70 year old woman is 3 days after a hip replacement. She has sudden pleuritic chest pain and breathlessness. HR 112 bpm, BP 128/80 mmHg, SpO2 90% on air. Her Wells score is above 4. Which investigation should be done FIRST to confirm the diagnosis?', 'With a ''PE likely'' Wells score (above 4), NICE recommends immediate CTPA (start interim anticoagulation if there will be a delay). D-dimer is used only when the Wells score is 4 or less, and is often raised after surgery anyway. If she is haemodynamically unstable (massive PE), bedside echocardiography and thrombolysis are considered.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
