  ('4bdc72f8-99cc-59a1-8269-c93f58dc4fc5', '9f2e7279-b377-5bba-afb8-094a92394242', 'A', 'Ventilation-perfusion scan after 2 weeks', false, 0),
  ('fed004b8-9b01-590e-9652-cedd46459a3c', '9f2e7279-b377-5bba-afb8-094a92394242', 'B', 'CT pulmonary angiography', true, 1),
  ('efaccf4a-bd88-5e57-91e6-8a4ff09cd970', '9f2e7279-b377-5bba-afb8-094a92394242', 'C', 'Lower limb X-ray', false, 2),
  ('48b5c160-24b5-5d25-a42d-2681488cedd7', '9f2e7279-b377-5bba-afb8-094a92394242', 'D', 'D-dimer', false, 3),
  ('dce6cbdb-001a-5c50-9cce-f8148b147f6e', '9f2e7279-b377-5bba-afb8-094a92394242', 'E', 'Echocardiogram', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('20da2367-8d01-5e93-92fe-53a6918848f3', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 60 year old man is reviewed at a pre-operative assessment clinic before elective surgery. Which feature would make it MOST appropriate to postpone surgery?', 'AAGBI/BHS guidance: patients can proceed to elective surgery if their primary care BP is below 160/100 mmHg. If there is no primary care record and the clinic BP is 180/110 mmHg or more, elective surgery should be postponed while hypertension is treated. Surgery is often postponed if HbA1c is above 69 mmol/mol to optimise control. Mild hypertension and well-controlled asthma are not reasons to cancel.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('14c9368d-cf0b-559b-8e43-9e13a3734fe5', '20da2367-8d01-5e93-92fe-53a6918848f3', 'A', 'Previous appendicectomy', false, 0),
  ('bcd21a4a-cf9d-5545-9d33-33c564c39b48', '20da2367-8d01-5e93-92fe-53a6918848f3', 'B', 'Blood pressure of 185/115 mmHg on repeated measurement', true, 1),
  ('089c2a0e-4700-5bd1-9ab6-9ebf0fcee06f', '20da2367-8d01-5e93-92fe-53a6918848f3', 'C', 'Well-controlled asthma', false, 2),
  ('87db15f1-298b-50f0-8e0e-59c8a50e5aaf', '20da2367-8d01-5e93-92fe-53a6918848f3', 'D', 'Blood pressure of 150/90 mmHg', false, 3),
  ('9f55ee1c-c4f2-5548-abdf-c27cdc7186eb', '20da2367-8d01-5e93-92fe-53a6918848f3', 'E', 'HbA1c of 62 mmol/mol', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('3ce42283-11c2-5042-9190-105ca0372547', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000018', 'sba', 'A 45 year old woman has a femoral nerve block for a fractured femur. Ten minutes later she has perioral tingling, tinnitus and agitation, then a seizure. Her ECG shows a broad-complex bradycardia. What is the SINGLE most important specific treatment?', 'Local anaesthetic systemic toxicity (LAST) causes CNS symptoms (perioral numbness, tinnitus, confusion, seizures), then cardiovascular toxicity (arrhythmias, cardiovascular collapse), especially with bupivacaine. Stop the injection, call for help, manage the airway, treat seizures with benzodiazepines, and give an IV 20% lipid emulsion bolus followed by an infusion (AAGBI guidance). CPR may need to be prolonged.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
