  ('2334b97f-fa9a-573c-8850-8bafc4aaad11', '3ce42283-11c2-5042-9190-105ca0372547', 'A', 'IV naloxone', false, 0),
  ('6e8c90f9-be37-520c-b348-2942c797065a', '3ce42283-11c2-5042-9190-105ca0372547', 'B', 'IV flumazenil', false, 1),
  ('247ca115-6081-55ae-9aee-b7eb67005f96', '3ce42283-11c2-5042-9190-105ca0372547', 'C', 'IV calcium gluconate only', false, 2),
  ('c01a76b6-6f88-5b2c-a9fb-4a38f5d09664', '3ce42283-11c2-5042-9190-105ca0372547', 'D', 'IV sodium bicarbonate only', false, 3),
  ('32f2f521-5b2e-5bcf-8b7b-9a725aa91a94', '3ce42283-11c2-5042-9190-105ca0372547', 'E', 'IV 20% lipid emulsion (Intralipid)', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('ae32f380-2aef-5ab2-981c-106357fd9daf', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 62 year old smoker has had a hoarse voice for 5 weeks. He has no other symptoms. What is the SINGLE most appropriate management?', 'NICE NG12 recommends a suspected cancer referral for laryngeal cancer in people aged 45 and over with persistent unexplained hoarseness. Smoking and alcohol are the main risk factors. A chest X-ray can be considered to look for an apical lung tumour compressing the recurrent laryngeal nerve, but this should not delay referral.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
