  ('6bc00dc1-33c9-57d3-8267-5728bfd0602d', 'ae32f380-2aef-5ab2-981c-106357fd9daf', 'A', 'Suspected cancer pathway referral (two-week wait) to ENT', true, 0),
  ('d7b8b177-b82f-5c3b-8e02-936206e616ab', 'ae32f380-2aef-5ab2-981c-106357fd9daf', 'B', 'Reassure and review in 3 months', false, 1),
  ('93f833d0-7b75-501d-9afe-b68ffa40122c', 'ae32f380-2aef-5ab2-981c-106357fd9daf', 'C', 'Course of oral amoxicillin', false, 2),
  ('ef78ce1c-3b76-5e64-9b07-532537552f4d', 'ae32f380-2aef-5ab2-981c-106357fd9daf', 'D', 'Inhaled corticosteroid', false, 3),
  ('94187a4f-425e-5016-802e-fe80fc23e7bd', 'ae32f380-2aef-5ab2-981c-106357fd9daf', 'E', 'Voice therapy only', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 21 year old woman has had a sore throat, fever and painful neck swelling for 3 days. She now has trismus, a muffled ''hot potato'' voice, and the uvula is pushed to the left. What is the SINGLE most appropriate management?', 'These are the features of a peritonsillar abscess (quinsy) on the right side. It needs same-day ENT assessment for aspiration or incision and drainage, IV antibiotics (such as benzylpenicillin with metronidazole) and analgesia. Watch for airway compromise. Interval tonsillectomy may be considered after recurrent quinsy.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('bf3ac844-ddf1-5cb2-a60c-bf62c8f9221b', 'c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'A', 'Oral prednisolone alone', false, 0),
  ('70cf5b0d-da69-5950-9740-e65de5f13996', 'c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'B', 'Discharge with analgesia', false, 1),
  ('896a0ba9-900b-52bf-8eb6-0e38c6400843', 'c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'C', 'Oral penicillin V and review in 1 week', false, 2),
  ('666d4625-e2db-5153-92b2-7a4bfabb90ca', 'c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'D', 'Urgent tonsillectomy the same day under local anaesthetic in primary care', false, 3),
  ('d31f0a19-0d7d-5621-b56f-780a32dbb3cf', 'c0a64aac-3863-5a55-a736-b4d6e41ef5b0', 'E', 'Same-day ENT referral for needle aspiration or incision and drainage with IV antibiotics', true, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 7 year old boy has had recurrent tonsillitis. Which pattern meets the SIGN/NICE criteria for considering tonsillectomy?', 'The SIGN 117 (Paradise) criteria, used in NICE CKS: sore throats are due to acute tonsillitis; episodes are disabling and prevent normal functioning; and there are 7 or more well-documented episodes in the preceding year, or 5 or more in each of the 2 preceding years, or 3 or more in each of the 3 preceding years. Other indications are recurrent quinsy and obstructive sleep apnoea.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9e487d4a-9ed9-57e1-9a4f-86942da0de2f', '0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'A', 'Any episode needing antibiotics', false, 0),
  ('b1b48375-b6b2-5108-8b81-e65a131fe446', '0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'B', '7 or more episodes in 1 year, or 5 or more per year for 2 years, or 3 or more per year for 3 years, with episodes disabling and preventing normal functioning', true, 1),
  ('6d8af0a5-3a62-5dd2-b9bc-3a36e2aa501b', '0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'C', '2 episodes in 1 year', false, 2),
  ('5563dc54-b9ec-5d23-a6cc-6e80b042d9c6', '0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'D', 'Snoring without apnoea', false, 3),
  ('8e17d983-d84f-53c6-bc33-190bb2a58934', '0bc17d79-9ece-5954-ab9e-ce7f30d76f03', 'E', 'Halitosis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('62d5c81d-5066-59de-9de1-200ea1c81232', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000026', 'sba', 'A 70 year old man has had recurrent right-sided epistaxis and right nasal obstruction for 2 months, with unilateral bloody discharge. He worked for many years as a carpenter in a hardwood furniture factory. What is the SINGLE most likely diagnosis?', 'Unilateral nasal obstruction, bloody discharge or epistaxis in an older person are red flags for sinonasal malignancy. Occupational exposure to hardwood dust is strongly linked to sinonasal (intestinal-type) adenocarcinoma. Bilateral polyps are usually benign. Juvenile angiofibroma occurs in adolescent boys. Refer on the suspected cancer pathway.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('9e60091a-23f3-5cc2-a46d-dc2481e78bc0', '62d5c81d-5066-59de-9de1-200ea1c81232', 'A', 'Nasal polyps (benign)', false, 0),
  ('03a0e2a9-ed4e-5034-b78f-a9b8fa67aacc', '62d5c81d-5066-59de-9de1-200ea1c81232', 'B', 'Juvenile angiofibroma', false, 1),
  ('8d0e4fee-3bb1-58d9-9be8-5a3c17d9b206', '62d5c81d-5066-59de-9de1-200ea1c81232', 'C', 'Septal haematoma', false, 2),
  ('ec9812ac-869c-549d-89e9-e4b5586c8b0b', '62d5c81d-5066-59de-9de1-200ea1c81232', 'D', 'Sinonasal adenocarcinoma', true, 3),
  ('049189eb-7906-5d7d-8d12-a64f09a46646', '62d5c81d-5066-59de-9de1-200ea1c81232', 'E', 'Allergic rhinitis', false, 4);
insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('7f305109-9f94-547d-bbb0-660833816252', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000036', 'sba', 'A couple''s first child has cystic fibrosis. Neither parent has the condition. What is the chance that their next child will be a carrier who is not affected?', 'Both parents must be carriers (autosomal recessive). Each pregnancy has a 25% chance of being affected, a 50% chance of being an unaffected carrier, and a 25% chance of being an unaffected non-carrier. Do not confuse this with the probability that an unaffected sibling is a carrier, which is 2/3, because the affected outcome has already been excluded.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
insert into public.question_options (id, question_id, label, body, is_correct, sort_order) values
  ('2a0fdbbd-43d8-55b2-8d1e-61f4ea2377a0', '7f305109-9f94-547d-bbb0-660833816252', 'A', '0%', false, 0),
  ('67a7a468-03d0-5127-856e-6cbed2196030', '7f305109-9f94-547d-bbb0-660833816252', 'B', '25%', false, 1),
  ('126fa476-2b38-5d48-a945-38b7dfe6c57b', '7f305109-9f94-547d-bbb0-660833816252', 'C', '50%', true, 2),
  ('1ff1c016-dfd3-5f85-9272-00b2d1c19f75', '7f305109-9f94-547d-bbb0-660833816252', 'D', '67%', false, 3),
