insert into public.questions (id, exam_id, topic_id, question_type, stem, explanation, difficulty, is_active, is_uk_practice, payload) values ('a73ef753-8860-518a-af62-d6e1aad9880c', 'a1000000-0000-4000-8000-000000000001', 'a2000000-0000-4000-8000-000000000027', 'sba', 'A 26 year old woman wants to know about the HPV vaccine. Which statement about the UK HPV programme is CORRECT?', 'Since September 2023 the UK routine schedule is one dose of HPV vaccine (Gardasil 9) for girls and boys in school Year 8. Men who have sex with men up to age 45 are offered it through sexual health clinics. Vaccinated women still need cervical screening, because the vaccine does not cover all oncogenic HPV types.', null, true, false, jsonb_build_object('source', 'plab1-xlsx-v2')) on conflict (id) do update set stem = excluded.stem, explanation = excluded.explanation, topic_id = excluded.topic_id, is_uk_practice = excluded.is_uk_practice, payload = excluded.payload, is_active = true, updated_at = now();
